CREATE TABLE `fixed_asset_inventory_plans` (
  `id` varchar(64) NOT NULL COMMENT '主键',
  `plan_no` varchar(255) DEFAULT NULL COMMENT '必填 唯一',
  `plan_name` varchar(255) DEFAULT NULL COMMENT '必填',
  `scope` varchar(255) DEFAULT NULL,
  `counter` varchar(255) DEFAULT NULL,
  `plan_date` datetime(3) DEFAULT NULL,
  `status` varchar(64) DEFAULT NULL COMMENT 'DOC_STATUS 必填',
  `items` longtext COMMENT '盘点明细 JSON：全公司资产可达数百项，TEXT(64KB) 会溢出',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `version` int DEFAULT '1' COMMENT '乐观锁版本',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='盘点计划';
