DROP TABLE IF EXISTS `system_workflow_flows`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `system_workflow_flows` (
  `id` varchar(64) NOT NULL COMMENT '主键',
  `code` varchar(255) DEFAULT NULL COMMENT '必填 唯一',
  `name` varchar(255) DEFAULT NULL COMMENT '必填',
  `biz_type` varchar(64) DEFAULT NULL COMMENT 'BUSINESS_TYPE 必填',
  `initiator` varchar(255) DEFAULT NULL,
  `initiator_role_id` varchar(255) DEFAULT NULL COMMENT '→org-roles',
  `enabled` tinyint(1) DEFAULT NULL,
  `steps` text,
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `version` int DEFAULT '1' COMMENT '乐观锁版本',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='工作流程';
/*!40101 SET character_set_client = @saved_cs_client */;

